dtsPropsFor.Kicker:
/** Small uppercase section label. Default brand tone is for light surfaces; tone="azure" is the lighter accent for dark backgrounds. */
children: React.ReactNode;
/** Color treatment. 'brand' (deep ocean, on light) or 'azure' (sky blue, on dark). */
tone?: 'brand' | 'azure';

dtsPropsFor.ContourLines:
/** Decorative topographic contour lines (aria-hidden). Sized/positioned entirely by the className you pass. */
className?: string;
/** 'hero' = larger 5-line motif behind page heroes; 'band' = flatter 3-line motif for dark CTA bands. */
variant?: 'hero' | 'band';

dtsPropsFor.PageHero:
/** Small uppercase label above the title. */
eyebrow: string;
/** Page title. May include a <span className="text-brand"> for the emphasized phrase. */
title: React.ReactNode;
/** Supporting lede paragraph. */
lede: React.ReactNode;
/** Optional content below the lede (e.g. anchor chips). */
children?: React.ReactNode;

dtsPropsFor.CtaBand:
/** Heading of the call-to-action band. */
title: string;
/** Supporting text under the heading. */
text: React.ReactNode;
/** Action buttons/links (use .cta .cta-azure / .cta-dark-ghost). */
children: React.ReactNode;
/** 'split' = heading left, actions right; 'center' = stacked and centered. */
align?: 'split' | 'center';
